<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Model;
class AttendanceDeviceEmployeeMapping extends Model { protected $fillable=['device_id','user_id','external_employee_id','external_user_code','effective_from','effective_to','status','remarks','created_by','updated_by']; protected $casts=['effective_from'=>'date','effective_to'=>'date']; public function device(){return $this->belongsTo(AttendanceDevice::class);} public function user(){return $this->belongsTo(User::class);} public function creator(){return $this->belongsTo(User::class,'created_by');} public function updater(){return $this->belongsTo(User::class,'updated_by');} public function logs(){return $this->hasMany(AttendanceDeviceLog::class,'user_id','user_id')->whereColumn('attendance_device_logs.device_id','attendance_device_employee_mappings.device_id');} }
